//! NZB intake validation acceptance: size caps and 4xx taxonomy.
//!
//! Contract for the paired build slice. Do not edit this file to make it
//! pass: implement the missing symbols in `src/nzb_intake.rs` (re-exported
//! through the existing `pub mod nzb_intake`) instead.
//!
//! Expected new public API in `nntune_ingest::nzb_intake`:
//!
//! ```text
//! pub const INTAKE_CONFIG_VERSION: u32 = 1;
//!
//! pub struct IntakeConfig {
//!     pub version: u32,
//!     pub max_nzb_bytes: usize,
//!     pub max_files: usize,
//!     pub max_segments: usize,
//!     pub max_declared_bytes: u64,
//! }
//! impl Default for IntakeConfig { /* versioned defaults matching the
//!     legacy MAX_* caps; max_declared_bytes large enough for the valid
//!     fixture below (200 declared bytes) and for the over-count /
//!     over-bytes fixtures to pass with defaults (5 segments, 1600 bytes) */ }
//!
//! pub fn validate_nzb_intake(
//!     body: &str,
//!     config: &IntakeConfig,
//! ) -> Result<Ok_, Err_>
//! where
//!     Ok_: { pub file_count: usize, pub segment_count: usize,
//!            pub declared_bytes: u64, .. },
//!     Err_: { pub code: u16, pub reason: String,
//!             pub segment_count: usize, pub declared_bytes: u64, .. },
//! ```
//!
//! Behaviour contract (synthetic NZBs only, no provider traffic):
//!
//! - Valid fixture with defaults -> `Ok` with exact counts.
//! - Malformed XML (still containing `<nzb` in the head, so the legacy
//!   substring pre-filter accepts it) -> `Err` with `code == 400` and
//!   `reason` mentioning `malform`, `xml`, or `parse` (case-insensitive).
//! - Segment-count over a tight `max_segments` -> `Err` with `code == 413`
//!   and `reason` mentioning `segment`, `count`, or `file`.
//! - Declared `bytes=` sum over a tight `max_declared_bytes` -> `Err` with
//!   `code == 413` and `reason` mentioning `byte`.
//! - Document bytes over a tight `max_nzb_bytes` -> `Err` with `code == 413`
//!   and `reason` mentioning `byte`, `size`, or `large`.
//! - The same over-count / over-bytes fixtures pass with
//!   `IntakeConfig::default()`: caps come from the versioned config, never
//!   from hardcoded branches.
//! - `INTAKE_CONFIG_VERSION == 1`, `default().version` matches it, and the
//!   default `max_nzb_bytes` / `max_files` / `max_segments` equal the legacy
//!   `MAX_NZB_BYTES` / `MAX_FILES` / `MAX_SEGMENTS` consts.
//! - Rejections carry the observed `segment_count` / `declared_bytes` so a
//!   client can render them.
//!
//! This file is intentionally RED until the build lands: it references
//! `IntakeConfig`, `INTAKE_CONFIG_VERSION`, and `validate_nzb_intake`,
//! which do not exist yet, so `cargo test --test
//! nzb_intake_validation_acceptance` fails to compile while the existing
//! `--lib` and `pipeline_e2e` suites stay green.

use nntune_ingest::dispatch::build_upload_dispatch;
use nntune_ingest::nzb_intake::{
    estimate_nzb, validate_nzb_intake, IntakeConfig, INTAKE_CONFIG_VERSION, MAX_FILES,
    MAX_NZB_BYTES, MAX_SEGMENTS,
};

/// Minimal well-formed NZB: 1 file, 2 segments, 200 declared bytes.
const VALID_NZB: &str = r#"<?xml version="1.0"?>
<nzb xmlns="http://www.newzbin.com/DTD/2003/nzb">
<file poster="a@b" date="1" subject="track01.flac">
<groups><group>alt.binaries.music</group></groups>
<segments>
<segment bytes="100" number="1">seg-one@synthetic.invalid</segment>
<segment bytes="100" number="2">seg-two@synthetic.invalid</segment>
</segments>
</file>
</nzb>"#;

/// Broken XML that still contains `<nzb` in the first head bytes, so the
/// legacy substring pre-filter accepts it: the second segment is never
/// closed, leaving `segments` / `file` / `nzb` unbalanced.
const MALFORMED_NZB: &str = r#"<?xml version="1.0"?>
<nzb xmlns="http://www.newzbin.com/DTD/2003/nzb">
<file poster="a@b" date="1" subject="track01.flac">
<groups><group>alt.binaries.music</group></groups>
<segments>
<segment bytes="100" number="1">seg-one@synthetic.invalid</segment>
<segment bytes="100" number="2">seg-two@synthetic.invalid
</segments>
</file>
</nzb>"#;

/// 1 file, 5 segments, 50 declared bytes: passes with defaults, exceeds a
/// tight `max_segments: 4` without coming near the document size cap.
const OVER_COUNT_NZB: &str = r#"<?xml version="1.0"?>
<nzb xmlns="http://www.newzbin.com/DTD/2003/nzb">
<file poster="a@b" date="1" subject="track05.flac">
<groups><group>alt.binaries.music</group></groups>
<segments>
<segment bytes="10" number="1">seg-01@synthetic.invalid</segment>
<segment bytes="10" number="2">seg-02@synthetic.invalid</segment>
<segment bytes="10" number="3">seg-03@synthetic.invalid</segment>
<segment bytes="10" number="4">seg-04@synthetic.invalid</segment>
<segment bytes="10" number="5">seg-05@synthetic.invalid</segment>
</segments>
</file>
</nzb>"#;

/// 1 file, 2 segments, 1600 declared bytes in a few hundred document bytes:
/// passes with defaults, exceeds a tight `max_declared_bytes: 1000`.
const OVER_BYTES_NZB: &str = r#"<?xml version="1.0"?>
<nzb xmlns="http://www.newzbin.com/DTD/2003/nzb">
<file poster="a@b" date="1" subject="track06.flac">
<groups><group>alt.binaries.music</group></groups>
<segments>
<segment bytes="800" number="1">seg-11@synthetic.invalid</segment>
<segment bytes="800" number="2">seg-12@synthetic.invalid</segment>
</segments>
</file>
</nzb>"#;

fn reason_is(reason: &str, needles: &[&str]) -> bool {
    let lower = reason.to_lowercase();
    needles.iter().any(|n| lower.contains(n))
}

#[test]
fn valid_accepts_with_default_config() {
    let report = validate_nzb_intake(VALID_NZB, &IntakeConfig::default())
        .expect("valid NZB must validate with defaults");
    assert_eq!(report.file_count, 1, "valid fixture has one file");
    assert_eq!(report.segment_count, 2, "valid fixture has two segments");
    assert_eq!(
        report.declared_bytes, 200,
        "100 + 100 declared bytes must be summed"
    );
}

#[test]
fn malformed_xml_is_400_with_reason() {
    // The legacy pre-filter only looks for the `<nzb` substring, so this
    // documents the gap the full validation must close.
    assert!(
        estimate_nzb(MALFORMED_NZB).is_ok(),
        "malformed fixture must still pass the substring pre-filter"
    );
    let err = validate_nzb_intake(MALFORMED_NZB, &IntakeConfig::default())
        .expect_err("broken XML must be rejected");
    assert_eq!(err.code, 400, "malformed XML is a 400");
    assert!(
        reason_is(&err.reason, &["malform", "xml", "parse"]),
        "reason must name the XML problem, got: {}",
        err.reason
    );
    // Reason fields exist for client rendering (no exact count pinned: the
    // parse fails before counts are known).
    let _ = err.segment_count;
    let _ = err.declared_bytes;
}

#[test]
fn over_count_is_413_with_segment_reason() {
    let tight = IntakeConfig {
        max_segments: 4,
        ..IntakeConfig::default()
    };
    let err = validate_nzb_intake(OVER_COUNT_NZB, &tight)
        .expect_err("5 segments over a max_segments: 4 cap must be rejected");
    assert_eq!(err.code, 413, "segment-count over cap is a 413");
    assert!(
        reason_is(&err.reason, &["segment", "count", "file"]),
        "reason must name the count dimension, got: {}",
        err.reason
    );
    assert_eq!(err.segment_count, 5, "rejection carries observed segments");
    assert_eq!(
        err.declared_bytes, 50,
        "rejection carries observed declared bytes"
    );
}

#[test]
fn over_declared_bytes_is_413_with_byte_reason() {
    let tight = IntakeConfig {
        max_declared_bytes: 1000,
        ..IntakeConfig::default()
    };
    let err = validate_nzb_intake(OVER_BYTES_NZB, &tight)
        .expect_err("1600 declared bytes over a 1000 cap must be rejected");
    assert_eq!(err.code, 413, "declared-bytes over cap is a 413");
    assert!(
        reason_is(&err.reason, &["byte"]),
        "reason must name the byte dimension, got: {}",
        err.reason
    );
    assert_eq!(err.segment_count, 2, "rejection carries observed segments");
    assert_eq!(
        err.declared_bytes, 1600,
        "rejection carries observed declared bytes"
    );
}

#[test]
fn document_bytes_over_cap_is_413() {
    let tight = IntakeConfig {
        max_nzb_bytes: 64,
        ..IntakeConfig::default()
    };
    assert!(
        VALID_NZB.len() > 64,
        "fixture must actually exceed the tight document cap"
    );
    let err = validate_nzb_intake(VALID_NZB, &tight)
        .expect_err("document bytes over cap must be rejected");
    assert_eq!(err.code, 413, "document-bytes over cap is a 413");
    assert!(
        reason_is(&err.reason, &["byte", "size", "large"]),
        "reason must name the size dimension, got: {}",
        err.reason
    );
}

#[test]
fn tight_caps_rejected_while_defaults_accept() {
    // Caps come from the versioned config, never from hardcoded branches:
    // the same bytes pass with defaults and fail with tight caps.
    let default = IntakeConfig::default();
    assert!(
        validate_nzb_intake(OVER_COUNT_NZB, &default).is_ok(),
        "over-count fixture must pass with defaults"
    );
    assert!(
        validate_nzb_intake(OVER_BYTES_NZB, &default).is_ok(),
        "over-bytes fixture must pass with defaults"
    );
    let tight_count = IntakeConfig {
        max_segments: 4,
        ..IntakeConfig::default()
    };
    assert!(validate_nzb_intake(OVER_COUNT_NZB, &tight_count).is_err());
    let tight_bytes = IntakeConfig {
        max_declared_bytes: 1000,
        ..IntakeConfig::default()
    };
    assert!(validate_nzb_intake(OVER_BYTES_NZB, &tight_bytes).is_err());
}

#[test]
fn config_is_versioned_and_defaults_match_legacy_caps() {
    assert_eq!(
        INTAKE_CONFIG_VERSION, 1,
        "intake config starts at version 1"
    );
    let default = IntakeConfig::default();
    assert_eq!(
        default.version, INTAKE_CONFIG_VERSION,
        "default carries the current version"
    );
    assert_eq!(
        default.max_nzb_bytes, MAX_NZB_BYTES,
        "default document cap matches the legacy const"
    );
    assert_eq!(
        default.max_files, MAX_FILES,
        "default file cap matches the legacy const"
    );
    assert_eq!(
        default.max_segments, MAX_SEGMENTS,
        "default segment cap matches the legacy const"
    );
    // The declared-bytes default must at least cover the valid + cap-probe
    // fixtures above (200 / 50 / 1600 bytes); the exact ceiling is the
    // build's choice.
    assert!(
        default.max_declared_bytes >= 1600,
        "default declared-bytes cap must accept the probe fixtures"
    );
}

#[test]
fn valid_fixture_still_queues_through_existing_dispatch() {
    // Regression guard on the current pipeline: the valid acceptance fixture
    // must keep reaching the queue once intake validation lands.
    assert!(estimate_nzb(VALID_NZB).is_ok());
    assert!(build_upload_dispatch("user_01", VALID_NZB).is_ok());
}
